sql:
SELECT *
FROM ChemicalCompounds
WHERE ContainsCalcium = 1 AND IsCarcinogenic = 1;

SELECT superhero_name, AVG(height_cm) AS average_height_cm
FROM superhero
GROUP BY superhero_name;

SELECT id
FROM cards
WHERE borderColor = 'black';

SELECT Text 
FROM comments 
WHERE CreationDate = '2010-07-19 19:25:47';

SELECT SUM(convertedManaCost) AS total_unconverted_mana_cost
FROM cards
WHERE artist = 'Rob Alexander';

SELECT GSoffered 
FROM schools 
WHERE Longitude = (SELECT MAX(Longitude) FROM schools);

SELECT COUNT(DISTINCT results.driverId) AS driver_count
FROM results
WHERE results.raceId = 18;

SELECT COUNT(Patient.ID) AS UnderagePatientsCount
FROM Patient
WHERE Patient.Birthday >= '1980-01-01' AND Patient.Birthday <= '1993-12-31';

SELECT COUNT(DISTINCT drivers.driverId) AS BritishDriversBornIn1980
FROM drivers
WHERE drivers.nationality = 'British' AND drivers.dob LIKE '1980-%';

SELECT COUNT(*) AS CarcinogenicMoleculesWithNitrogen
FROM Molecules
WHERE ContainsNitrogen = 1 AND IsCarcinogenic = 1;

SELECT COUNT(*) AS UserCount
FROM users
WHERE UpVotes > 100 AND DownVotes > 1;

SELECT COUNT(*) AS TagCount
FROM tags
WHERE Id < 15 AND Count <= 20;

SELECT COUNT(*) AS triple_type_bonds
FROM bond
WHERE bond_type = 'triple';

SELECT COUNT(*) AS infinite_power_cards
FROM cards
WHERE power = '∞';

SELECT originalType 
FROM cards 
WHERE name = 'Ancestor''s Chosen';

SELECT users.DisplayName
FROM users
WHERE strftime('%Y', users.CreationDate) = '2011';

SELECT COUNT(*) AS count_of_superheroes_without_publisher
FROM superhero
WHERE publisher_id IS NULL;

SELECT SUM(wins) AS total_victories
FROM driverStandings
WHERE position = 91;

SELECT DISTINCT account_id
FROM account
WHERE frequency = 'monthly';

SELECT COUNT(*) AS PostCount
FROM posts
WHERE Tags LIKE '%careers%';

SELECT eye_colour_id 
FROM superhero 
WHERE skin_colour_id = 1;

SELECT p.CommentCount AS CommentCount
FROM posts p
WHERE p.Score = (
    SELECT MAX(Score)
    FROM posts
);

SELECT Player.player_name
FROM Player
WHERE (strftime('%Y', 'now') - strftime('%Y', Player.birthday)) >= 35;

SELECT COUNT(*) AS BritishDriversBornAfter1980
FROM drivers
WHERE nationality = 'British' AND dob > '1980-01-01';

SELECT MAX(Consumption) AS HighestMonthlyConsumption
FROM yearmonth
WHERE strftime('%Y', Date) = '2012';

SELECT DISTINCT bond.bond_type
FROM bond
JOIN connected ON bond.bond_id = connected.bond_id
WHERE connected.atom_id IN (
    SELECT atom_id FROM connected WHERE atom_id2 LIKE '%Carbon%'
) OR connected.atom_id2 IN (
    SELECT atom_id FROM connected WHERE atom_id2 LIKE '%Carbon%'
);

SELECT *
FROM bonds
WHERE atom_elements LIKE '%phosphorus%' AND atom_elements LIKE '%nitrogen%';

SELECT COUNT(DISTINCT Player.player_api_id) AS player_count
FROM Player
WHERE Player.birthday > '1990-01-01';

SELECT AVG(LDH) AS Average_LDH
FROM Laboratory
WHERE LDH BETWEEN 100 AND 240;

SELECT AVG(height_cm) AS average_height
FROM superhero
WHERE skin_colour_id IS NULL;

SELECT name 
FROM cards 
WHERE text IS NOT NULL;

SELECT manaCost 
FROM cards 
WHERE name = 'Ancestor\'s Chosen';

SELECT COUNT(*) AS BountyPostsCount
FROM votes
WHERE BountyAmount > 30;

SELECT setCode 
FROM sets 
WHERE releaseDate = '2017-07-14';

SELECT element
FROM bonds
WHERE bond_type = 'triple';

SELECT *
FROM molecules
WHERE carcinogenic = 'No' AND atom_count > 5;
